import {ruleFor,stageDefaults} from './styles.js';
export function rulesMarkup(p,key,esc){return `<details class="rules-panel"><summary>Aturan tahap ini <span>${p.rules?.[key]!==undefined?'Khusus proyek':'Bawaan'}</span></summary><p class="note">Aturan ini ikut dalam prompt. Simpan untuk proyek ini atau jadikan bawaan proyek berikutnya.</p><label for="stageRules">Instruksi tambahan</label><textarea id="stageRules">${esc(ruleFor(p,key))}</textarea><div class="row"><button id="saveProjectRules">Simpan untuk proyek</button><button id="saveDefaultRules">Jadikan bawaan</button><button id="resetStageRules">Pakai bawaan</button></div><p id="ruleState" role="status"></p></details>`;}
export function bindRules(p,key,changed,notify,rerender){const q=id=>document.getElementById(id);if(!q('stageRules'))return;q('saveProjectRules').onclick=()=>{p.rules??={};p.rules[key]=q('stageRules').value;changed();q('ruleState').textContent='Aturan khusus proyek tersimpan.';};q('saveDefaultRules').onclick=()=>{try{const defaults=JSON.parse(localStorage.getItem('ruang-stage-rules')||'{}');defaults[key]=q('stageRules').value;localStorage.setItem('ruang-stage-rules',JSON.stringify(defaults));p.rules??={};delete p.rules[key];changed();q('ruleState').textContent='Aturan bawaan tersimpan di perangkat ini.';}catch(e){notify('Aturan bawaan belum tersimpan: '+e.message);}};q('resetStageRules').onclick=()=>{p.rules??={};delete p.rules[key];changed();rerender();};}
